"use client";

/**
 * Create/edit form bound to `createIssueSchema` through `zodResolver`.
 *
 * The schema is the same object the Server Action re-parses, so a field the
 * client accepts can never be one the server rejects — that shared definition
 * is the whole point of keeping the Zod schemas outside both layers.
 *
 * Must call (do not reimplement): createIssueSchema
 */
import { zodResolver } from "@hookform/resolvers/zod";
import { useForm, useWatch } from "react-hook-form";
import { Button } from "@/components/ui/button";
import { ErrorMessage } from "@/components/ui/error-message";
import { FormField } from "@/components/ui/form-field";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { useFormAction } from "@/hooks/use-form-action";
import { createIssueSchema, type CreateIssueInput } from "@/schemas/issue";
import type { ActionResult } from "@/types/api";
import type { IsoTimestamp, LabelId, OrgId, ProjectId, UserId } from "@/types/common";
import type { Issue, IssueLabel } from "@/types/issue";
import type { MemberWithUser } from "@/types/member";
import type { ReactElement } from "react";
import { IssueAssigneePicker } from "./issue-assignee-picker";
import { IssueDueDateField } from "./issue-due-date-field";
import { IssueLabelPicker } from "./issue-label-picker";
import { IssuePrioritySelect } from "./issue-priority-select";
import { IssueStatusSelect } from "./issue-status-select";

export type IssueFormProps = {
  orgId: OrgId;
  projectId: ProjectId;
  defaultValues?: Partial<CreateIssueInput>;
  members: readonly MemberWithUser[];
  labels: readonly IssueLabel[];
  onSubmit: (input: CreateIssueInput) => Promise<ActionResult<Issue>>;
};

export function IssueForm(props: IssueFormProps): ReactElement | null {
  const { orgId, projectId, defaultValues, members, labels, onSubmit } = props;

  const form = useForm({
    resolver: zodResolver(createIssueSchema),
    defaultValues: {
      orgId,
      projectId,
      title: "",
      description: null,
      status: "backlog",
      priority: "none",
      assigneeId: null,
      parentId: null,
      estimate: null,
      dueAt: null,
      labelIds: [],
      ...defaultValues,
    },
  });

  const { submit, pending, error } = useFormAction(onSubmit, {
    onSuccess: () => form.reset(),
  });

  const values = useWatch({ control: form.control });
  const fieldError = (name: keyof CreateIssueInput): string | null =>
    form.formState.errors[name]?.message ?? null;

  return (
    <form
      className="space-y-4"
      onSubmit={form.handleSubmit((input) => submit(input))}
    >
      <FormField
        name="title"
        label="Title"
        required
        error={fieldError("title")}
      >
        <Input
          name="title"
          value={values.title ?? ""}
          placeholder="Something is broken"
          invalid={fieldError("title") !== null}
          onChange={(value) => form.setValue("title", value)}
        />
      </FormField>

      <FormField name="description" label="Description">
        <Textarea
          name="description"
          rows={6}
          value={values.description ?? ""}
          placeholder="What happened, and what did you expect?"
          onChange={(value) =>
            form.setValue("description", value.length === 0 ? null : value)
          }
        />
      </FormField>

      <div className="grid gap-4 sm:grid-cols-2">
        <FormField name="status" label="Status">
          <IssueStatusSelect
            value={values.status ?? "backlog"}
            onChange={(status) => form.setValue("status", status)}
          />
        </FormField>

        <FormField name="priority" label="Priority">
          <IssuePrioritySelect
            value={values.priority ?? "none"}
            onChange={(priority) => form.setValue("priority", priority)}
          />
        </FormField>

        <FormField name="assigneeId" label="Assignee">
          <IssueAssigneePicker
            value={(values.assigneeId ?? null) as UserId | null}
            members={members}
            onChange={(userId) => form.setValue("assigneeId", userId)}
          />
        </FormField>

        <FormField name="dueAt" label="Due date">
          <IssueDueDateField
            value={(values.dueAt ?? null) as IsoTimestamp | null}
            onChange={(dueAt) => form.setValue("dueAt", dueAt)}
          />
        </FormField>
      </div>

      <FormField name="labelIds" label="Labels">
        <IssueLabelPicker
          value={(values.labelIds ?? []) as unknown as readonly LabelId[]}
          labels={labels}
          onChange={(labelIds) => form.setValue("labelIds", [...labelIds])}
        />
      </FormField>

      <ErrorMessage message={error?.message ?? null} />

      <Button type="submit" loading={pending} disabled={pending}>
        Create issue
      </Button>
    </form>
  );
}

import { z } from "zod";
import type { IssuePriority, IssueStatus } from "@/types/issue";
import {
  archiveScopeSchema,
  isoTimestampSchema,
  issueIdSchema,
  labelIdSchema,
  orgIdSchema,
  pageRequestSchema,
  projectIdSchema,
  userIdSchema,
} from "./common";

export const issueStatusSchema = z.enum([
  "backlog",
  "todo",
  "in_progress",
  "in_review",
  "done",
  "canceled",
]);

export const issuePrioritySchema = z.enum([
  "none",
  "low",
  "medium",
  "high",
  "urgent",
]);

export const createIssueSchema = z.object({
  orgId: orgIdSchema,
  projectId: projectIdSchema,
  title: z.string().min(3, "give the issue a title").max(200),
  description: z.string().max(20_000).nullable().default(null),
  status: issueStatusSchema.default("backlog"),
  priority: issuePrioritySchema.default("none"),
  assigneeId: userIdSchema.nullable().default(null),
  parentId: issueIdSchema.nullable().default(null),
  estimate: z.number().int().min(0).max(100).nullable().default(null),
  dueAt: isoTimestampSchema.nullable().default(null),
  labelIds: z.array(labelIdSchema).max(20).default([]),
});

export const updateIssueSchema = z.object({
  orgId: orgIdSchema,
  issueId: issueIdSchema,
  title: z.string().min(3).max(200).optional(),
  description: z.string().max(20_000).nullable().optional(),
  priority: issuePrioritySchema.optional(),
  estimate: z.number().int().min(0).max(100).nullable().optional(),
  dueAt: isoTimestampSchema.nullable().optional(),
  labelIds: z.array(labelIdSchema).max(20).optional(),
});

export const changeIssueStatusSchema = z.object({
  orgId: orgIdSchema,
  issueId: issueIdSchema,
  status: issueStatusSchema,
});

export const assignIssueSchema = z.object({
  orgId: orgIdSchema,
  issueId: issueIdSchema,
  assigneeId: userIdSchema.nullable(),
});

export const archiveIssueSchema = z.object({
  orgId: orgIdSchema,
  issueId: issueIdSchema,
});

export const issueFilterSchema = z
  .object({
    orgId: orgIdSchema,
    projectId: projectIdSchema.optional(),
    status: z.array(issueStatusSchema).optional(),
    priority: z.array(issuePrioritySchema).optional(),
    assigneeId: userIdSchema.nullable().optional(),
    authorId: userIdSchema.optional(),
    labelIds: z.array(labelIdSchema).optional(),
    query: z.string().max(200).optional(),
    dueBefore: isoTimestampSchema.optional(),
  })
  .extend(pageRequestSchema.shape)
  .extend(archiveScopeSchema.shape);

/** Board drag-and-drop payload: move one issue into a column at an index. */
export const moveIssueSchema = z.object({
  orgId: orgIdSchema,
  issueId: issueIdSchema,
  toStatus: issueStatusSchema,
  toIndex: z.number().int().min(0),
});

const _statusParity: IssueStatus = "in_review" satisfies z.infer<
  typeof issueStatusSchema
>;
const _priorityParity: IssuePriority = "urgent" satisfies z.infer<
  typeof issuePrioritySchema
>;
void _statusParity;
void _priorityParity;

export type CreateIssueInput = z.infer<typeof createIssueSchema>;
export type UpdateIssueInput = z.infer<typeof updateIssueSchema>;
export type ChangeIssueStatusInput = z.infer<typeof changeIssueStatusSchema>;
export type AssignIssueInput = z.infer<typeof assignIssueSchema>;
export type IssueFilterInput = z.infer<typeof issueFilterSchema>;
export type MoveIssueInput = z.infer<typeof moveIssueSchema>;

